   -- eb4 4                                        
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		RAM_RdAddr_Start <= (others => '1');
   		REG_RLEN <= (others => '0');
   	elsif rising_edge(Clk) then
   		if(State_c = ST_IDLE) then
   			RAM_RdAddr_Start <= (others => '1');
   			REG_RLEN <= (others => '0');
   		elsif(State_c = ST_RD_ADDR) and (ARVALID_r2 = '1') then
   			RAM_RdAddr_Start <= ARADDR_r2;
   			REG_RLEN         <= ARLEN_r2;
   		end if;
   	end if;
   end process;
   
   
