   			RAM_RdEn <= '1';
   		else
   			RAM_RdEn <= '0';
   		end if;
   	end if;
   end process;
   
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		RAM_RdAddr <= (others => '1');
   
   	elsif rising_edge(Clk) then
   		if(State_c = ST_RD_DATA) and (RREADY_r2 = '1') then
   			RAM_RdAddr <= RAM_RdAddr_Start + ('0'&RAM_RdCnt);
   			
   		end if;
   	end if;
   end process;
   
   
   
