   			RVALID_b1 <=  '1';
   		else
   			RVALID_b1  <= '0';
   		end if;
   	end if;
   end process;
   
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		RVALID_b2  <= '0';
   		RVALID     <= '0';
   	elsif rising_edge(Clk) then
   		RVALID_b2 <= RVALID_b1;
   		RVALID    <= RVALID_b2;
   	end if;
   end process;
   
   process(Reset, Clk) begin
   	if(Reset = '1') then
   		RDATA      <= (others => '0');
