   		RAM_RdCnt <= (others => '0');
   	elsif rising_edge(Clk) then
   		if(Add_RAM_RdCnt = '1') then
   			if(End_RAM_RdCnt = '1') then
   				RAM_RdCnt <= (others => '0');
   			else
   				RAM_RdCnt <=  RAM_RdCnt + X"01";
   			end if;
   		end if;
   	end if;
   end process;
   
   Add_RAM_RdCnt <= '1' when (State_c = ST_RD_DATA) and (RREADY_r2 = '1') else '0';
   End_RAM_RdCnt <= '1' when (Add_RAM_RdCnt = '1') and (RAM_RdCnt = REG_RLEN) else '0';
   
   
   process(Clk) begin
   	if rising_edge(Clk) then
   		RLAST_b <= End_RAM_RdCnt;
   		RLAST_b2 <= RLAST_b;
   	end if;
   end process;
   
